void CanApp_SetWakeupMode_NM(uint8 LeCanApp_u_WakeUpStateChange)
{
    SeCanApp_u_WakeupMode = (LeCanApp_u_WakeUpStateChange != 0U) ? CanApp_WAKEUP_ACTIVE : CanApp_WAKEUP_PASSIVE;
    /* inform lower layer (CanTrcv) about the wakeup mode to avoid reverse dependency */
    CanTrcv_SetWakeupMode(SeCanApp_u_WakeupMode);
}

