static void CanApp_CheckPositiveWakeup(void)
{
    static uint8 SeCanApp_u_WakeupFlag = 0U;

     /* ========== Active Wake-up Mode ========== */
    if (SeCanApp_u_WakeupMode == 1U)
    {
        /*Request and maintain the network as long as communication is allowed (typically enabled after initialization). */
        if (0U != SeCanApp_u_EnableRequestCommunication)
        {
            if (SeCanApp_u_WakeupFlag != 0xAAU)
            {
                (void)CclRequestCommunication(0U);
                SeCanApp_u_WakeupFlag = 0xAAU;
            }
        }
        else
        {
            /* When communication is prohibited (which rarely occurs), the network is disconnected. */
            if (0xAAU == SeCanApp_u_WakeupFlag)
            {
                CclReleaseCommunication(0U);
                SeCanApp_u_WakeupFlag = 0U;
            }
        }
        /* In the active mode, completely ignore the subsequent diagnostic timer and other logic, and directly return. */
        return;
    }

     /* ========== Passive Wake-up Mode ========== */
    
    if(0x0U != SeCanApp_u_DiagReqNetFlag)/*Request network for 6s when receive diag ID*/
    {
        SeCanApp_u_DiagReqNetFlag = 0U;
        SeCanApp_w_DiagReqNetCount = 1000U; /*5s*/
    }
    if(0x0U != SeCanApp_w_DiagReqNetCount)
    {
        SeCanApp_w_DiagReqNetCount--;
    }
    
    if(((0U != SeCanApp_w_DiagReqNetCount) || (CanMsg_BcmPwrStsFb_OFF != SeCanApp_u_BcmPwrStsFb))
     && (0U != SeCanApp_u_EnableRequestCommunication))
    {
        if (CanNm_NmState[0] != NM_STATE_PREPARE_BUS_SLEEP)
        {
            (void)CclRequestCommunication(0U);
             SeCanApp_u_WakeupFlag = 0xAAU;
        }
    }
    else
    {
        if(0xAAU == SeCanApp_u_WakeupFlag)
        {
            CclReleaseCommunication(0U);
            SeCanApp_u_WakeupFlag = 0U;
        }
    }
} 
