uint8 GetCanApp_u_NetWorkSleepAllowed(void)
{
    uint8 LeCanApp_u_NetWorkSleep =CeCanApp_u_SleepNotAllowed;

    if((0u == SeCanApp_u_NetWorkStaus)&&( CeCanTrcv_e_Standbymode == GetCanTrcv_CurrentMode()))
    {
        LeCanApp_u_NetWorkSleep = CeCanApp_u_SleepAllowed;
    }
    else
    {
        LeCanApp_u_NetWorkSleep = CeCanApp_u_SleepNotAllowed;
    }
    return LeCanApp_u_NetWorkSleep;
}

