static void CanApp_SignalRecMainFunc(void)
{
    if(NMStatus_NETON == CanApp_u_GetNetWorkStaus()) 
    {
        /*VIU_FR_1C3*/
        if((uint8)1u == SeCanApp_u_MsgReceiveSts[VeCanApp_e_VIU_FR_1C3])
        {
            SeCanApp_u_MsgReceiveSts[VeCanApp_e_VIU_FR_1C3] = 0U;
            IlEnterCriticalEspVehSpd();
            SeCanApp_u_EspVehSpd = IlGetRxEspVehSpd();
            SeCanApp_u_EspVehSpdVld = IlGetRxEspVehSpdVld();
            IlLeaveCriticalEspVehSpd();
        }

        /*VIU_FR_288*/
        if((uint8)1u == SeCanApp_u_MsgReceiveSts[VeCanApp_e_VIU_FR_288])
        {
            SeCanApp_u_MsgReceiveSts[VeCanApp_e_VIU_FR_288] = 0U;
            IlEnterCriticalBcmPwrStsFb();
            SeCanApp_u_BcmPwrStsFb = IlGetRxBcmPwrStsFb();
            IlLeaveCriticalBcmPwrStsFb();
        }

        /*VIU_FR_2EC*/
        if((uint8)1u == SeCanApp_u_MsgReceiveSts[VeCanApp_e_VIU_FR_2EC])
        {
            SeCanApp_u_MsgReceiveSts[VeCanApp_e_VIU_FR_2EC] = 0U;
            IlEnterCriticalVcuGearPosn();
            SeCanApp_u_VcuGearPosn = IlGetRxVcuGearPosn();
            SeCanApp_u_VcuVehGearPosnVld = IlGetRxVcuVehGearPosnVld();
            IlLeaveCriticalVcuGearPosn();
        }
        /*VIU_FR_2EF*/
        if((uint8)1u == SeCanApp_u_MsgReceiveSts[VeCanApp_e_VIU_FR_2EF])
        {
            SeCanApp_u_MsgReceiveSts[VeCanApp_e_VIU_FR_2EF] = 0U;
            IlEnterCriticalCdcTotMilg();
            SeCanApp_u_CdcTotMilg = IlGetRxCdcTotMilg();
            IlLeaveCriticalCdcTotMilg();
        }

        /*VIU_FR_2F7*/
        if((uint8)1u == SeCanApp_u_MsgReceiveSts[VeCanApp_e_VIU_FR_2F7])
        {
            SeCanApp_u_MsgReceiveSts[VeCanApp_e_VIU_FR_2F7] = 0U;
            IlEnterCriticalTboxLocalTiDate();
            SeCanApp_u_TboxLocalTiDate = IlGetRxTboxLocalTiDate();
            SeCanApp_u_TboxLocalTiHr = IlGetRxTboxLocalTiHr();
            SeCanApp_u_TboxLocalTiMins = IlGetRxTboxLocalTiMins();
            SeCanApp_u_TboxLocalTiMth = IlGetRxTboxLocalTiMth();
            SeCanApp_u_TboxLocalTiSec = IlGetRxTboxLocalTiSec();
            SeCanApp_u_TboxLocalTiVld = IlGetRxTboxLocalTiVld();
            SeCanApp_u_TboxLocalTiYear = IlGetRxTboxLocalTiYear();
            IlLeaveCriticalTboxLocalTiDate();
        }

        /*VIU_FR_3D1*/
        if((uint8)1u == SeCanApp_u_MsgReceiveSts[VeCanApp_e_VIU_FR_3D1])
        {
            SeCanApp_u_MsgReceiveSts[VeCanApp_e_VIU_FR_3D1] = 0U;
            IlEnterCriticalDcdcOperSts();
            SeCanApp_u_DcdcOperSts = IlGetRxDcdcOperSts();
            IlLeaveCriticalDcdcOperSts();
        }

        /*VIU_FR_3D3*/
        if((uint8)1u == SeCanApp_u_MsgReceiveSts[VeCanApp_e_VIU_FR_3D3])
        {
            SeCanApp_u_MsgReceiveSts[VeCanApp_e_VIU_FR_3D3] = 0U;
            IlEnterCriticalBcuOperMod();
            SeCanApp_u_BcuOperMod = IlGetRxBcuOperMod();
            IlLeaveCriticalBcuOperMod();
        }

        /*VIU_FR_3ED*/
        if((uint8)1u == SeCanApp_u_MsgReceiveSts[VeCanApp_e_VIU_FR_3ED])
        {
            SeCanApp_u_MsgReceiveSts[VeCanApp_e_VIU_FR_3ED] = 0U;
            IlEnterCriticalFridgeUnlockCtrl();
            SeCanApp_u_FridgeUnlockCtrl = IlGetRxFridgeUnlockCtrl();
            SeCanApp_u_FridgeDoorWarnTimeSet = IlGetRxFridgeDoorWarnTimeSet();
            SeCanApp_u_FridgeChdLockReq = IlGetRxFridgeChdLockReq();
            SeCanApp_u_EgySaveModReq = IlGetRxEgySaveModReq();
            SeCanApp_u_FridgeWorkReq = IlGetRxFridgeWorkReq();
            SeCanApp_u_FridgeQFunReq = IlGetRxFridgeQFunReq();
            SeCanApp_u_ContinueWorkSw = IlGetRxContinueWorkSw();
            SeCanApp_u_ContinueWorkTimeSet = IlGetRxContinueWorkTimeSet();
            SeCanApp_u_FridgeUVLedReq = IlGetRxFridgeUVLedReq();
            SeCanApp_u_FridgeUVLedWorkTimeSet = IlGetRxFridgeUVLedWorkTimeSet();
            SeCanApp_u_FridgeModeReq = IlGetRxFridgeModeReq();
            SeCanApp_u_FridgeCoolTempReq = IlGetRxFridgeCoolTempReq();
            SeCanApp_u_FridgeHeatTempReq = IlGetRxFridgeHeatTempReq();
            SeCanApp_u_VrhcuExOffReas = IlGetRxVrhcuExOffReas();
            SeCanApp_u_VrhcuONReas = IlGetRxVrhcuONReas();
            IlLeaveCriticalFridgeUnlockCtrl();
        }

        if (0U == SeCanApp_u_MsgPresentSts[VeCanApp_e_VIU_FR_3ED])
        {
            SeCanApp_u_VrhcuExOffReas = 0U;
            SeCanApp_u_VrhcuONReas = 0U;
        }
        if (0U == SeCanApp_u_MsgPresentSts[VeCanApp_e_VIU_FR_288])
        {
            SeCanApp_u_BcmPwrStsFb = CanMsg_BcmPwrStsFb_OFF;
        }
        if (0U == SeCanApp_u_MsgPresentSts[VeCanApp_e_VIU_FR_1C3])
        {
            //SeCanApp_u_EspVehSpd = 0x1FFFU;
           // SeCanApp_u_EspVehSpdVld = 0x1U;
        }
        if (0U == SeCanApp_u_MsgPresentSts[VeCanApp_e_VIU_FR_2EC])
        {
           // SeCanApp_u_VcuVehGearPosnVld = 0x1U;
        }
        if (0U == SeCanApp_u_MsgPresentSts[VeCanApp_e_VIU_FR_2EF])
        {
            SeCanApp_u_CdcTotMilg = 0xFFFFFFU;
        }
        if (0U == SeCanApp_u_MsgPresentSts[VeCanApp_e_VIU_FR_2F7])
        {
            SeCanApp_u_TboxLocalTiVld = 0x1U;
        }
    }
    else
    {
        /*Keep value*/
    }
}
