 void CanApp_InitMemory(void)
 {
    uint8 i;
    SeCanApp_u_NetWorkStaus = 1u;
    SeCanApp_u_BusOffStaus = 0u;
    SeCanApp_BusOffOccurNum =0u;

    /*VIU_FR_1C3*/
    SeCanApp_u_EspVehSpd = 0u;
    SeCanApp_u_EspVehSpdVld = 0u;

    /*VIU_FR_288*/
    SeCanApp_u_BcmPwrStsFb = CanMsg_BcmPwrStsFb_OFF;

    /*VIU_FR_2EC*/
    SeCanApp_u_VcuGearPosn =0u;
    SeCanApp_u_VcuVehGearPosnVld =0u;
    /*VIU_FR_2EF*/
    SeCanApp_u_CdcTotMilg =0u;
    /*VIU_FR_2F7*/
    SeCanApp_u_TboxLocalTiDate =0u;
    SeCanApp_u_TboxLocalTiHr =0u;
    SeCanApp_u_TboxLocalTiMins =0u;
    SeCanApp_u_TboxLocalTiMth =0u;
    SeCanApp_u_TboxLocalTiSec =0u;
    SeCanApp_u_TboxLocalTiVld =0u;
    SeCanApp_u_TboxLocalTiYear =0u;

    /*VIU_FR_3D1*/
    SeCanApp_u_DcdcOperSts = 2u;//0u;

    /*VIU_FR_3D3*/
    SeCanApp_u_BcuOperMod =0u;

    /*VIU_FR_3ED*/
    SeCanApp_u_FridgeUnlockCtrl =0u;
    SeCanApp_u_FridgeDoorWarnTimeSet =0u;
    SeCanApp_u_FridgeChdLockReq =0u;
    SeCanApp_u_EgySaveModReq =0u;
    SeCanApp_u_FridgeWorkReq =0u;
    SeCanApp_u_FridgeQFunReq =0u;
    SeCanApp_u_ContinueWorkSw =0u;
    SeCanApp_u_ContinueWorkTimeSet =0u;
    SeCanApp_u_FridgeUVLedReq =0u;
    SeCanApp_u_FridgeUVLedWorkTimeSet =0u;
    SeCanApp_u_FridgeModeReq =0u;
    SeCanApp_u_FridgeCoolTempReq =0u;
    SeCanApp_u_FridgeHeatTempReq =0u;
    SeCanApp_u_VrhcuExOffReas =0u;
    SeCanApp_u_VrhcuONReas =0u;

    for(i = 0u;i <(uint8)VeCanApp_e_MsgMaxNum;i++)
    {
        SeCanApp_u_MsgPresentSts[i] = 1U;
        SeCanApp_u_MsgReceiveSts[i] = 0U;
        MessageRxReceiveIsOk[i] = 0U;
    }
    
    SeCanApp_u_ReqNetFlag = 0U;
    SeCanApp_u_DiagReqNetFlag = 0U;
    SeCanApp_w_DiagReqNetCount = 0U;
    SeCanApp_u_EnableImmediateNmTx = 0U;
    SeCanApp_u_EnableRequestCommunication = 0U;
    SeCanApp_u_WakeUpSource_Nm = 0U;
    SeCanApp_u_AwakeSource_Nm = 0U;
 }
