uint8 CanCbk_GetBusOffDtcConditionState(void)/*BusOff DTC*/ //GGL
{  
	 uint8 LeCanApp_u_RetVal = 0u;
	if( 5U <= SeCanApp_BusOffOccurNum )
	{
		LeCanApp_u_RetVal = CeCanApp_e_True;
	}
	else
	{
		LeCanApp_u_RetVal = CeCanApp_e_False;
	}
	
	return LeCanApp_u_RetVal;
}

